  static <T> T find(View v,Class<T> type){if(type.isInstance(v))return type.cast(v);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){T x=find(((ViewGroup)v).getChildAt(i),type);if(x!=null)return x;}return null;}
