  static void await(Instrumentation t,RawEditActivity a)throws Exception{long until=SystemClock.uptimeMillis()+20000;boolean[] ready={false};while(!ready[0]&&SystemClock.uptimeMillis()<until){main(t,()->{View save=named(a.getWindow().getDecorView(),"保存");ready[0]=save!=null&&save.isEnabled()&&find(a.getWindow().getDecorView(),RawEditPad.class)!=null;});Thread.sleep(30);}require(ready[0],"synthetic ready");}
  static RawEditCurvePanel panel(RawEditActivity a){return find(a.getWindow().getDecorView(),RawEditCurvePanel.class);}
  static void send(View v,long down,long now,int action,float... points){MotionEvent e;
    if(points.length==2)e=MotionEvent.obtain(down,now,action,points[0],points[1],0);
    else{int count=points.length/2;MotionEvent.PointerProperties[] ids=new MotionEvent.PointerProperties[count];MotionEvent.PointerCoords[] coords=new MotionEvent.PointerCoords[count];for(int i=0;i<count;i++){ids[i]=new MotionEvent.PointerProperties();ids[i].id=i;ids[i].toolType=MotionEvent.TOOL_TYPE_FINGER;coords[i]=new MotionEvent.PointerCoords();coords[i].x=points[i*2];coords[i].y=points[i*2+1];coords[i].pressure=coords[i].size=1;}e=MotionEvent.obtain(down,now,action,count,ids,coords,0,0,1,1,0,0,InputDevice.SOURCE_TOUCHSCREEN,0);}
    e.setSource(InputDevice.SOURCE_TOUCHSCREEN);try{v.dispatchTouchEvent(e);}finally{e.recycle();}}
  static float[] xy(RawEditCurvePanel p,float x,float y){return new float[]{p.getLeft()+p.graph.getLeft()+p.graph.sx(x),p.getTop()+p.graph.getTop()+p.graph.sy(y)};}
  static void tap(RawEditCurvePanel p,float x,float y){float[] q=xy(p,x,y);long n=SystemClock.uptimeMillis();send((View)p.getParent(),n,n,MotionEvent.ACTION_DOWN,q);send((View)p.getParent(),n,n+20,MotionEvent.ACTION_UP,q);}
  static void drag(RawEditCurvePanel p,float x,float y,float tx,float ty){float[] q=xy(p,x,y),z=xy(p,tx,ty);long n=SystemClock.uptimeMillis();View picture=(View)p.getParent();send(picture,n,n,MotionEvent.ACTION_DOWN,q);send(picture,n,n+20,MotionEvent.ACTION_MOVE,z);send(picture,n,n+40,MotionEvent.ACTION_UP,z);}
  static Object field(Object target,String name){try{java.lang.reflect.Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
  static void capture(Instrumentation t,RawEditActivity a,String name)throws Exception{
    long limit=SystemClock.uptimeMillis()+20000;boolean[] ready={false};while(!ready[0]&&SystemClock.uptimeMillis()<limit){main(t,()->{RawEditFullSession full=(RawEditFullSession)field(a,"fullSession");ready[0]=full!=null&&full.isPrepared()&&field(a,"pendingFullPreview")==null&&!(Boolean)field(a,"previewSwapQueued")&&!((java.util.concurrent.atomic.AtomicBoolean)field(a,"queued")).get()&&(Long)field(a,"rendered")==((java.util.concurrent.atomic.AtomicLong)field(a,"revision")).get();});Thread.sleep(30);}if(!ready[0])main(t,()->{RawEditFullSession f=(RawEditFullSession)field(a,"fullSession");throw new AssertionError("capture gate prepared="+(f!=null&&f.isPrepared())+" pending="+(field(a,"pendingFullPreview")!=null)+" swapping="+field(a,"previewSwapQueued")+" queued="+field(a,"queued")+" rendered="+field(a,"rendered")+" revision="+field(a,"revision")+" interacting="+field(a,"interacting"));});
    CountDownLatch frame=new CountDownLatch(1);main(t,()->{View decor=a.getWindow().getDecorView();decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();});require(frame.await(5,TimeUnit.SECONDS),"curve capture frame committed");
    CountDownLatch done=new CountDownLatch(1);Bitmap[] bmp={null};int[] result={-1};JSONObject meta=new JSONObject();
    main(t,()->{View decor=a.getWindow().getDecorView(),root=((ViewGroup)a.findViewById(android.R.id.content)).getChildAt(0);RawEditCurvePanel p=panel(a);float d=a.getResources().getDisplayMetrics().density;try{meta.put("density",d);meta.put("font",a.getResources().getConfiguration().fontScale);meta.put("content",new JSONArray(new int[]{root.getPaddingLeft(),root.getPaddingTop(),root.getWidth()-root.getPaddingRight(),root.getHeight()-root.getPaddingBottom()}));meta.put("panel",new JSONArray(new int[]{p.getLeft(),p.getTop()+root.getPaddingTop()+Math.round(56*d),p.getRight(),p.getBottom()+root.getPaddingTop()+Math.round(56*d)}));meta.put("recipe",new JSONArray(state(a).snapshot()));}catch(JSONException e){throw new AssertionError(e);}
      bmp[0]=Bitmap.createBitmap(decor.getWidth(),decor.getHeight(),Bitmap.Config.ARGB_8888);PixelCopy.request(a.getWindow(),bmp[0],code->{result[0]=code;done.countDown();},new Handler(Looper.getMainLooper()));});
    require(done.await(5,TimeUnit.SECONDS)&&result[0]==PixelCopy.SUCCESS,"curve PixelCopy");File dir=new File(a.getCacheDir(),"tone-curve-check");dir.mkdirs();try(OutputStream out=new FileOutputStream(new File(dir,name+".png"))){bmp[0].compress(Bitmap.CompressFormat.PNG,100,out);}finally{bmp[0].recycle();}try(Writer out=new FileWriter(new File(dir,name+".json"))){out.write(meta.toString(2));}
  }
  static RawEditHistory history(RawEditActivity a){try{java.lang.reflect.Field f=RawEditActivity.class.getDeclaredField("history");f.setAccessible(true);return (RawEditHistory)f.get(a);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
